export async function runJob(pool, task) {
  const resource = await pool.acquire();
  let taskFailed = false;
  let taskError;
  try {
    return await task(resource);
  } catch (error) {
    taskFailed = true;
    taskError = error;
    throw error;
  } finally {
    try {
      await resource.close();
    } catch (cleanupError) {
      if (taskFailed) {
        throw new AggregateError([taskError, cleanupError], 'task and cleanup both failed');
      }
      throw cleanupError;
    }
  }
}

