export function detectClaudeAuthentication(env, statusOutput) {
  const environmentSource = env.ANTHROPIC_API_KEY
    ? 'ANTHROPIC_API_KEY'
    : env.ANTHROPIC_AUTH_TOKEN
      ? 'ANTHROPIC_AUTH_TOKEN'
      : undefined;

  try {
    const status = JSON.parse(statusOutput);
    const authenticated = status.loggedIn === true;
    if (authenticated && environmentSource) {
      return { authenticated: true, credentialSource: environmentSource };
    }
    return {
      authenticated,
      authDetail: authenticated ? `authenticated (${status.authMethod ?? 'unknown'})` : 'run `claude auth login`',
    };
  } catch {
    return environmentSource
      ? { authenticated: true, credentialSource: environmentSource }
      : { authenticated: false, authDetail: 'unable to read Claude credential status' };
  }
}

